package com.bank.payroll;

import java.util.*;
import java.util.logging.*;

public class PayrollDemo {
    private static final Logger log = Logger.getLogger("Payroll");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = new ArrayList<>(List.of(
            new Employee(1L, "Rajesh", 95000.0),
            new Employee(2L, "Priya", 250000.0),
            new Employee(3L, "Amit", 120000.0),
            new Employee(4L, "Sneha", 180000.0)
        ));
        PayrollService service = new PayrollService();
        List<Employee> sorted = service.sortBySalaryDesc(staff);
        log.info("Payroll report (highest salary first):");
        sorted.forEach(e -> log.info(() ->
            String.format("  %-8s | %.2f", e.getName(), e.getSalary())));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final double salary;
    Employee(Long id, String name, double salary) { this.id = id; this.name = name; this.salary = salary; }
    String getName() { return name; }
    double getSalary() { return salary; }
}

// ─── Would be in service/PayrollService.java ───
class PayrollService {
    // reversed() flips ascending salary into descending.
    // Production tip: comparingDouble avoids boxing for a primitive double key.
    List<Employee> sortBySalaryDesc(List<Employee> employees) {
        return employees.stream()
            .sorted(Comparator.comparing(Employee::getSalary).reversed())
            .toList();
    }
}
